var zgjVideoSlotsByID = func() map[string]zgjVideoSlot {
	registry := make(map[string]zgjVideoSlot, len(zgjVideoSlots))
	for _, slot := range zgjVideoSlots {
		registry[slot.ID] = slot
	}
	return registry
}()

func zgjVideoSlotFor(source string) (zgjVideoSlot, bool) {
	key := strings.ToLower(strings.TrimSpace(source))
	if key == "" {
		return zgjVideoSlot{}, false
	}
	if slot, ok := zgjVideoSlotsByID[key]; ok {
		return slot, true
	}
	if canonical := canonicalProviderSource(key); canonical != key {
		if slot, ok := zgjVideoSlotsByID[canonical]; ok {
			return slot, true
		}
	}
	return zgjVideoSlot{}, false
}

func zgjVideoSlotsAll() []zgjVideoSlot {
	out := make([]zgjVideoSlot, len(zgjVideoSlots))
	copy(out, zgjVideoSlots)
	return out
}
